def is_power_of_5(x):
    if x <= 0:
        return False
    while x > 1:
        if x % 5 != 0:
            return False
        x //= 5
    return x == 1

results = {}
for n in range(3, 16):
    value = (2**n) - 3
    is_power = is_power_of_5(value)
    results[n] = (value, is_power)

for n, (value, is_power) in results.items():
    print(f"n={n}: 2^{n} - 3 = {value}. Is a power of 5: {is_power}")

import math

def is_power_of_two(x):
    if x <= 0:
        return False
    return (x & (x - 1) == 0)

print("Checking $k=1$ to $k=10$ for $2^n = 5^k + 3$:")
solutions = []
for k in range(1, 11):
    val = 5**k + 3
    if is_power_of_two(val):
        n = int(math.log2(val))
        if n >= 3:
            solutions.append((k, n))
        else:
            # Should not happen for k >= 1 since 5^k + 3 >= 8
            pass
    print(f"k={k}: 5^{k} + 3 = {val}. Is power of 2? {is_power_of_two(val)}")

print("\nSolutions found (k, n):", solutions)

def check_power_of_5(m):
    if m <= 0:
        return False
    if m == 1:
        return True
    while m > 1 and m % 5 == 0:
        m //= 5
    return m == 1

solutions = []
for n in range(3, 35): # Check up to n=34
    value = 2**n - 3
    if check_power_of_5(value):
        solutions.append(n)
print(f"Solutions found up to n=34: {solutions}")
